document.addEventListener('submit',async e=>{e.preventDefault();let f=e.target,v=formValues(f);try{switch(f.id){
 case 'rewards-form':await act('settings',v,'Reward settings saved.');return;
 case 'fallback-form':await act('settings',v,'Fallback settings saved. Press Start / resume if playback is stopped.');return;
 case 'appearance-form':await act('settings',{theme_colors:v},'Theme saved.');return;
 case 'custom-form':{const list=[...state.settings.custom_commands],index=Number(v.index);delete v.index;if(index<0)list.push(v);else list[index]=v;await act('settings',{custom_commands:list},'Custom command saved.');render();return}
 case 'search-form':await submitSong(v);return;
 case 'playlist-form':{let id=v.id.split('/').pop().split('?')[0];const d=await act('playlist',{id});playlistResults=d.tracks;$('#playlist-results').innerHTML=results(playlistResults);return}
 case 'rules-form':{v.block_explicit=!v.allow_explicit;delete v.allow_explicit;const roles={};Object.keys(state.settings.roles).forEach(r=>{roles[r]={};['pending','session','cooldown','skip','request_method'].forEach(k=>{roles[r][k]=v[r+'.'+k];delete v[r+'.'+k]})});v.roles=roles;v.blocked_artists=v.blocked_artists.split('\n');v.blocked_tracks=v.blocked_tracks.split('\n');await act('settings',v,'Request rules saved.');break}
 case 'commands-form':await act('settings',{commands:v},'Command names saved.');break;

  case 'connections-form':await act('settings',v,'Connections saved. Connect the accounts, then start the bot.');break;
 case 'analyze-form':{const d=await act('analyze',v);$('#analysis').innerHTML=d.findings.map(x=>`<p><b>${esc(x.match)}</b> — ${esc(x.suggestion)}</p>`).join('');break}
 }}catch(e){notice(e.message,true)}});
document.addEventListener('change',async e=>{try{switch(e.target.id){case 'settings-page':navigate(e.target.value);break;case 'allow-explicit':try{await act('settings',{block_explicit:!e.target.checked},'Explicit-song setting saved.')}catch(err){e.target.checked=!state.settings.block_explicit;throw err}break;case 'follow-spotify-playlist':await act('settings',{spotify_follow_current_playlist:e.target.checked},'Playlist mode saved.');render();break;case 'spotify-native-queue':try{await act('settings',{spotify_native_queue:e.target.checked},'Queue mode saved.');render()}catch(err){e.target.checked=!!state.spotify_queue?.enabled;throw err}break;case 'hide-playlist':await act('settings',{hide_playlist:e.target.checked});queueSignature='';render();break;case 'quick-requests':await act('settings',{requests_enabled:e.target.checked});break;case 'widget-branding':try{await act('settings',{widget_branding:e.target.checked},'Widget branding saved.')}catch(err){e.target.checked=state.settings.widget_branding;throw err}break;case 'widget-equalizer-style':await act('settings',{widget_equalizer_style:e.target.value});break;case 'widget-equalizer':await act('settings',{widget_equalizer:e.target.checked});break;case 'import-widget':await importWidget(e.target.files[0]);break;case 'theme':await act('settings',{theme:e.target.checked?'dark':'light'});break;case 'provider-mode':await act('settings',{provider_mode:e.target.value},'Source selection saved for the next song.');break;case 'device-select':await saveDevice(e.target);break;case 'playlist-select':document.querySelector('[name=id]').value=e.target.value;$('#playlist-form').requestSubmit();break;case 'log-file':if(e.target.files[0]){if(e.target.files[0].size>1000000)throw Error('Choose a log smaller than 1 MB.');document.querySelector('[name=text]').value=await e.target.files[0].text()}break;case 'tools':if(e.target.value==='exit'){if(confirm('Exit NextUp and stop its bot and playback?')){await api('exit',{});notice('NextUp is stopping. You can close this window.')}}else if(e.target.value)navigate(e.target.value);e.target.value='';break;case 'twitchMenu':if(e.target.value==='connections')navigate('connections');else if(e.target.value)await act('bot',{action:e.target.value});e.target.value='';break}}catch(e){notice(e.message,true)}});


let queueSignature='',dragging=false;
function applyColors(){if(!state)return;for(const k of Object.keys(themeDefaults)){document.body.style.removeProperty('--'+k)}for(const [k,v] of Object.entries(state.settings.theme_colors||{}))document.body.style.setProperty('--'+k,v)}
function syncLive(){if(!state)return;const c=state.playback.starting||state.playback.current||state.queue.current;syncLivePlayer();const qsig=JSON.stringify(state.queue.items);if(qsig!==queueSignature&&!dragging){if($('#upcoming-panel'))$('#upcoming-panel').innerHTML=upcoming();if($('#popout-queue'))$('#popout-queue').innerHTML=state.queue.items.map((x,i)=>row(x,i)).join('')||'<p>No upcoming requests.</p>';if(view==='queue'){const panel=$('#queue-items');if(panel)panel.innerHTML=queueRows()}queueSignature=qsig;preparePanels()}syncPlaybackButtons();if($('#spotify-queue-status'))$('#spotify-queue-status').textContent=state.spotify_queue?.error||(state.spotify_queue?.following_playlist?'Following your active Spotify playlist · requests use Spotify’s queue':state.spotify_queue?.enabled?`${state.spotify_queue.sent} requests sent to Spotify · ${state.spotify_queue.uncertain} need checking`:'');if($('#fallback-status'))$('#fallback-status').textContent=state.settings.spotify_follow_current_playlist?(state.playback.following_spotify_playlist?'Following Spotify’s current playlist':'Start a playlist in Spotify to follow it'):state.playback.fallback_note||(state.playback.fallback_active?'Playing from your fallback playlist':state.settings.fallback_enabled?(!['mixed',state.settings.fallback_provider].includes(state.settings.provider_mode)?'Selected fallback platform is disabled by Playback source':'Playlist not checked yet — use Check saved playlist'):'Fallback is off');if($('#queue-count'))$('#queue-count').textContent=queueCounts();if($('#queue-playback-status'))$('#queue-playback-status').textContent=state.playback.status;document.querySelectorAll('.playback-error').forEach(el=>el.textContent=state.playback.error||'');progressSample={seconds:state.playback.starting?0:state.playback.progress,at:performance.now(),playing:state.playback.status==='Playing',duration:c?.track.duration||0};if(view==='widgets')widgetEditorSync()}
let progressSample={seconds:0,at:0,playing:false,duration:0};
function animateProgress(){const p=progressSample,extra=p.playing?Math.min(5,(performance.now()-p.at)/1000):0,seconds=Math.min(p.duration,p.seconds+extra);document.querySelectorAll('[data-progress-fill]').forEach(e=>e.style.width=(p.duration?seconds/p.duration*100:0)+'%');document.querySelectorAll('[data-progress-time]').forEach(e=>e.textContent=time(seconds));requestAnimationFrame(animateProgress)}
function restoreSections(){let saved={};try{saved=JSON.parse(localStorage.getItem('nextup-sections')||'{}')}catch{}document.querySelectorAll('details[data-collapse]').forEach(d=>{if(d.dataset.collapse in saved)d.open=saved[d.dataset.collapse]})}
document.addEventListener('toggle',e=>{if(!e.target.matches('details[data-collapse]'))return;let saved={};try{saved=JSON.parse(localStorage.getItem('nextup-sections')||'{}')}catch{}saved[e.target.dataset.collapse]=e.target.open;localStorage.setItem('nextup-sections',JSON.stringify(saved))},true);
document.addEventListener('input',e=>{if(e.target.dataset.color){const k=e.target.dataset.color;$('[data-hex='+k+']').value=e.target.value;document.body.style.setProperty('--'+k,e.target.value)}if(e.target.dataset.hex&&/^#[0-9a-f]{6}$/i.test(e.target.value)){const k=e.target.dataset.hex;$('[data-color='+k+']').value=e.target.value;document.body.style.setProperty('--'+k,e.target.value)}});
async function extraClick(b){if(await moderatorClick(b))return true;if(await widgetAudioClick(b))return true;if(b.dataset.presetPreview){widgetSavedPreview(b.dataset.presetPreview);return true;}if(await widgetClick(b))return true;if(b.id==='restore-panels'){for(const k of Object.keys(localStorage)){if(k.startsWith('nextup-panel:')||k==='nextup-sections')localStorage.removeItem(k)}render();document.querySelectorAll('details[data-collapse]').forEach(d=>d.open=true);return true}if(b.dataset.forgetSpotify){await act('queue',{action:'forget-spotify',id:b.dataset.forgetSpotify},'Removed from NextUp tracking. Spotify’s queue is unchanged.');return true}if(b.id==='open-popout'){if(state.desktop)await api('desktop-popout',{});else window.open('/popout#'+key,'NextUpPopout','width=960,height=680');return true}if(b.id==='minimize-window'){await api('desktop-minimize',{});return true}if(b.id==='reset-colors'){await act('settings',{theme_colors:{}},'Default theme restored.');render();return true}if(['collapse-sections','expand-sections'].includes(b.id)){document.querySelectorAll('details').forEach(d=>d.open=b.id==='expand-sections');document.querySelectorAll('.panel-fold').forEach(p=>{if((p.getAttribute('aria-expanded')==='true')!==(b.id==='expand-sections'))p.click()});return true}if(b.dataset.customDelete!==undefined){const list=state.settings.custom_commands.filter((_,i)=>i!==Number(b.dataset.customDelete));await act('settings',{custom_commands:list});render();return true}if(b.dataset.customEdit!==undefined){const f=$('#custom-form'),i=Number(b.dataset.customEdit);f.elements.index.value=i;for(const[k,v]of Object.entries(state.settings.custom_commands[i])){if(f.elements[k]){if(typeof v==='boolean')f.elements[k].checked=v;else f.elements[k].value=v}}f.scrollIntoView({block:'center'});return true}if(b.dataset.exportWidget){const k=b.dataset.exportWidget;download('NextUp-'+k+'-widget.json',{format:'nextup-widget-v1',name:'My '+k+' widget',layout:k==='now'?'spectrum':k,equalizer:state.settings.widget_equalizer,equalizer_style:state.settings.widget_equalizer_style,label:(state.settings.widget_branding?'NEXTUP • ':'')+(k==='queue'?'UP NEXT':'NOW PLAYING'),colors:{...themeDefaults,...state.settings.theme_colors}});notice('Preset exported. Share the JSON file or attach it to your project submission.');return true}if(b.dataset.presetCopy!==undefined){const i=Number(b.dataset.presetCopy),p=state.settings.widget_presets[i],base=state.widgets[p.layout==='spectrum'?'now':p.layout];await navigator.clipboard.writeText(base+'&preset_id='+encodeURIComponent(p.id));notice('Widget URL copied.');return true}if(b.dataset.presetRemove!==undefined){await act('settings',{widget_presets:state.settings.widget_presets.filter((_,i)=>i!==Number(b.dataset.presetRemove))});render();return true}return false}
async function importWidget(file){return widgetImport(file)}
let draggedId=null;
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-queue-id]');if(!row)return;dragging=true;draggedId=row.dataset.queueId;e.dataTransfer.setData('text/plain',draggedId);e.dataTransfer.effectAllowed='move';row.classList.add('dragging')});
document.addEventListener('dragover',e=>{if(draggedId&&e.target.closest('[data-queue-id]')){e.preventDefault();e.dataTransfer.dropEffect='move'}});
document.addEventListener('drop',async e=>{const target=e.target.closest('[data-queue-id]');if(!target||!draggedId)return;e.preventDefault();const ids=state.queue.items.map(x=>x.id),from=ids.indexOf(draggedId),to=ids.indexOf(target.dataset.queueId);dragging=false;draggedId=null;if(from<0||to<0)return;ids.splice(to,0,ids.splice(from,1)[0]);try{await act('queue',{action:'reorder',ids},'Queue order saved.');syncLive()}catch{}});
document.addEventListener('dragend',()=>{dragging=false;draggedId=null;document.querySelectorAll('.dragging').forEach(e=>e.classList.remove('dragging'))});
if(location.pathname==='/popout'){document.body.classList.add('popout-mode')}

renderNav();refresh().catch(e=>notice(e.message,true));setInterval(()=>refresh(false).catch(()=>{}),1000);requestAnimationFrame(animateProgress);

function preparePanels(){document.querySelectorAll('#view .panel:not(details)').forEach((panel,i)=>{const h=panel.querySelector('h2');if(!h||h.closest('.panel')!==panel||h.querySelector('.panel-fold'))return;const id=view+':'+i,button=document.createElement('button');button.type='button';button.className='panel-fold';button.textContent='−';button.title='Collapse section';button.setAttribute('aria-expanded','true');h.append(button);const saved=localStorage.getItem('nextup-panel:'+id)==='closed';const set=closed=>{panel.classList.toggle('panel-minimized',closed);button.textContent=closed?'+':'−';button.setAttribute('aria-expanded',String(!closed));h.classList.add('panel-heading');for(let node=h;node&&node!==panel;node=node.parentElement)node.classList.add('panel-heading-row');button.title=closed?'Expand section':'Collapse section';button.setAttribute('aria-label',(closed?'Expand ':'Collapse ')+h.textContent.replace(/[+−]/g,'').trim())};set(saved);button.addEventListener('click',e=>{e.stopPropagation();set(!panel.classList.contains('panel-minimized'));localStorage.setItem('nextup-panel:'+id,panel.classList.contains('panel-minimized')?'closed':'open')})})}

function syncPlaybackButtons(){
 if(!state)return;
 const busy=!!(playbackPending||state.playback.busy||state.playback.starting);
 // The click handler runs before the next state poll. Set busy styling in the
 // same synchronous update as disabled, including when the request finishes.
 document.querySelectorAll('.listening-card').forEach(card=>card.setAttribute('aria-busy',String(busy)));
 document.querySelectorAll('[data-play]').forEach(b=>{
  b.disabled=!!busy||(b.dataset.play==='next'&&!state.settings.skip_enabled&&!!(state.playback.current||state.playback.failed_item||state.playback.starting));
  b.setAttribute('aria-busy',String(busy));
 });
}

function normalizeSwitches(){document.querySelectorAll('input[type="checkbox"]').forEach(el=>el.setAttribute('role','switch'))}
function updateDuration(){const input=document.querySelector('[name="max_seconds"]'),out=$('#duration-readout');if(!input||!out)return;const n=Number(input.value);out.textContent=input.value!==''&&Number.isInteger(n)&&n>=0?Math.floor(n/60)+' min '+String(n%60).padStart(2,'0')+' sec':'Choose a limit';}
document.addEventListener('input',e=>{if(e.target.name==='max_seconds')updateDuration()});
function equalizerOptions(value){return [['bars','Bars'],['rounded','Rounded'],['mirror','Mirror wave'],['led','LED segments'],['circle-bars','Circular bars'],['circle-wave','Circular wave'],['orb','Flowing orb'],['circle-dots','Fine spectrum · dotted tips'],['particle-sphere','Particle sphere']].map(([v,label])=>`<option value="${v}" ${v===(value||'bars')?'selected':''}>${label}</option>`).join('')}
function moderatorPanel(){const m=state.moderation;return `<details class="panel" id="moderator-panel" data-collapse="moderators"><summary>Moderators & request approval</summary><div class="control-grid"><label class="check"><input id="moderators-enabled" type="checkbox" ${state.settings.moderators_enabled?'checked':''}>Enable moderator access</label><label class="check"><input id="moderator-review-all" type="checkbox" ${state.settings.require_approval?'checked':''}>Require approval for viewer requests</label></div><div class="row"><button id="moderator-link" ${state.settings.moderators_enabled?'':'disabled'}>Create secure internet link</button><button id="moderator-copy-link">Copy review link</button></div><p class="hint" id="moderator-url">${esc(m.url)}${m.online?'':' · Local PC only. Internet links require cloudflared installed once.'}</p><form id="moderator-form" class="fieldgrid"><label>Moderator name<input name="name" required maxlength="60" placeholder="Twitch username or display name"></label><div class="control-grid">${toggle('Can approve','approve',true)}${toggle('Can reject','reject',true)}</div><button ${state.settings.moderators_enabled?'':'disabled'}>Create pairing code</button></form><div id="moderator-pair-result" role="status"></div><p class="hint">Share the secure link and code privately. Codes expire in 10 minutes and work once. Moderators can view the current song, queue and loaded fallback playlist, and review requests. Temporary links change after restart.</p><div>${m.members.map(x=>`<div class="moderator-row"><span><b>${esc(x.name)}</b><small>${[x.approve?'Approve':'',x.reject?'Reject':''].filter(Boolean).join(' · ')}</small></span><button data-moderator-revoke="${x.id}">Revoke access</button></div>`).join('')}${m.pending.map(x=>`<div class="moderator-row"><span>${esc(x.name)} <small>Awaiting pairing</small></span><button data-moderator-revoke="${x.id}">Cancel code</button></div>`).join('')}</div></details>`}
async function moderatorClick(b){if(b.dataset.moderatorRevoke){await act('moderator-revoke',{id:b.dataset.moderatorRevoke},'Access revoked.');render();return true}if(b.id==='moderator-copy-link'){await navigator.clipboard.writeText(state.moderation.url);notice(state.moderation.online?'Review link copied.':'Local-only link copied. Create a secure internet link for remote moderators.');return true}if(b.id==='moderator-link'){b.disabled=true;try{await api('moderator-link',{});await refresh();notice('Secure review link ready.')}finally{b.disabled=false}return true}return false}
document.addEventListener('change',async e=>{if(!['moderators-enabled','moderator-review-all'].includes(e.target.id))return;try{await act('settings',{[e.target.id==='moderators-enabled'?'moderators_enabled':'require_approval']:e.target.checked});render()}catch(err){e.target.checked=!e.target.checked;notice(err.message,true)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='moderator-form')return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const result=await api('moderator-create',formValues(e.target));await refresh(false);const box=$('#moderator-pair-result');box.replaceChildren();const code=document.createElement('strong');code.className='pair-code';code.textContent=result.code;box.append(code,document.createTextNode(' · Expires in 10 minutes'));}catch(err){notice(err.message,true)}finally{b.disabled=false}});
